    if (isPrimitiveType()) {
        return (TypeNode) getAccessNodeParent().getFirstChildOfType(ASTType.class).getChild(0);
    }
    if (!isTypeInferred()) {
        return (TypeNode) getAccessNodeParent().getFirstChildOfType(ASTType.class).getChild(0).getChild(0);
    }
    return null;
}

