                alert = record.value();
            } else {
                alertDataQueue.offer(record.value());
            }
            index++;
        }
        alertDataConsumer.commitAsync();
    } catch (Exception e){
        log.error(e.getMessage());
    } finally {
        lock1.unlock();
    }
    return alert;
}

